uint32_t ic_table_def_get_table_id(IC_TABLE_DEF *table_def);
uint32_t ic_table_def_get_table_version(IC_TABLE_DEF *table_def);
uint32_t ic_table_def_get_num_fields(IC_TABLE_DEF *table_def);
