uint32_t ic_table_def_get_field_size(IC_TABLE_DEF *table_def,
                                     uint32_t field_id);
/* Precision and scale for DECIMAL; precision holds the fractional second
   digits for TIME2/DATETIME2/TIMESTAMP2; bits for BIT. */
uint32_t ic_table_def_get_field_precision(IC_TABLE_DEF *table_def,
                                          uint32_t field_id);
uint32_t ic_table_def_get_field_scale(IC_TABLE_DEF *table_def,
                                      uint32_t field_id);
uint32_t ic_table_def_get_field_charset(IC_TABLE_DEF *table_def,
                                        uint32_t field_id);
int ic_table_def_is_field_nullable(IC_TABLE_DEF *table_def,
                                   uint32_t field_id);
int ic_table_def_is_field_key(IC_TABLE_DEF *table_def, uint32_t field_id);
int ic_table_def_is_field_distribution_key(IC_TABLE_DEF *table_def,
                                           uint32_t field_id);
int ic_table_def_is_field_autoincrement(IC_TABLE_DEF *table_def,
                                        uint32_t field_id);

/* Primary key fields in key order. */
uint32_t ic_table_def_get_num_key_fields(IC_TABLE_DEF *table_def);
uint32_t ic_table_def_get_key_field_id(IC_TABLE_DEF *table_def,
                                       uint32_t key_order);

/* Table properties relevant to node selection. */
