/* ------------------------------------------------------------------ */
/* IC_RECORD                                                           */
/* ------------------------------------------------------------------ */

uint32_t ic_record_get_num_fields(IC_RECORD *record);
uint32_t ic_record_get_row_size(IC_RECORD *record);
