/* ------------------------------------------------------------------ */
/* IC_APID_QUERY                                                       */
/* ------------------------------------------------------------------ */

/*
  A query object is defined once and reused many times. It ties a table
  (or unique index) to a key record and an attribute record. The rows
  themselves are passed with each call in the *_ARGS struct, so the same
  query object can be used with different row buffers.

  Completion handling: after a poll, a completed query is either handled
  in its callback or fetched with ic_apid_conn_get_next_executed_query().
  ic_apid_query_is_failed() tells quickly whether anything went wrong;
  ic_apid_query_get_error() has the details. A completed query is idle
  again and can be used for the next call without ic_apid_query_reset();
  reset is only needed to drop conditions and assignments that were not
  marked as kept.
*/
int ic_apid_query_create(IC_APID_GLOBAL *global,
                         IC_TABLE_DEF *table_def,
                         IC_RECORD *key_record,
                         IC_RECORD *attr_record,
                         IC_APID_QUERY **query);
int ic_apid_query_create_unique(IC_APID_GLOBAL *global,
                                IC_INDEX_DEF *index_def,
                                IC_RECORD *key_record,
                                IC_RECORD *attr_record,
                                IC_APID_QUERY **query);
void ic_apid_query_free(IC_APID_QUERY *query);
int ic_apid_query_reset(IC_APID_QUERY *query);

int ic_apid_query_is_failed(IC_APID_QUERY *query);
const IC_APID_ERROR *ic_apid_query_get_error(IC_APID_QUERY *query);
void *ic_apid_query_get_user_reference(IC_APID_QUERY *query);
IC_TRANSACTION *ic_apid_query_get_transaction(IC_APID_QUERY *query);
IC_TABLE_DEF *ic_apid_query_get_table_def(IC_APID_QUERY *query);
/* For reads: number of attribute bytes received (0 for a row not found
   under IC_IGNORE_ERROR, with error code 626). */
uint32_t ic_apid_query_get_result_length(IC_APID_QUERY *query);

/*
  WHERE conditions on a query. One condition per query; it is evaluated in
  the data node before the read or write. Either create one on the query
  or map one created on the global object by its id. A condition created
  on the query is released when the query completes unless
  ic_apid_query_keep_where() was called for this execution.
*/
int ic_apid_query_create_where_condition(IC_APID_QUERY *query,
                                         IC_WHERE_CONDITION **cond);
int ic_apid_query_map_where_condition(IC_APID_QUERY *query,
                                      uint32_t global_cond_id);
void ic_apid_query_keep_where(IC_APID_QUERY *query);

/*
  Conditional assignments on an update query. First declare how many, then
  create or map each by position. Assignments are executed in order and
  each sees the results of the previous ones.
*/
int ic_apid_query_create_conditional_assignments(IC_APID_QUERY *query,
                                                 uint32_t num_assignments);
int ic_apid_query_create_conditional_assignment(
    IC_APID_QUERY *query,
    uint32_t position,
    IC_CONDITIONAL_ASSIGNMENT **assign);
int ic_apid_query_map_conditional_assignment(IC_APID_QUERY *query,
                                             uint32_t position,
                                             uint32_t global_assign_id);
void ic_apid_query_keep_conditional_assignments(IC_APID_QUERY *query);

/* ------------------------------------------------------------------ */
/* IC_WHERE_CONDITION                                                  */
/* ------------------------------------------------------------------ */

/*
  A WHERE condition is built by walking the condition tree left-deep and
  emitting one call per node. Boolean nodes (AND, OR, XOR) open two
  subroutines and return their ids; comparisons end a subroutine; field
  and constant reads and calculations put values into typed memory
  addresses handed out by the API. Subroutine 0 is the top level.

  WHERE a = 1 AND b < (c + 3) becomes:

    ic_where_define_boolean(cond, 0, &left, &right, IC_AND);
    ic_where_read_field_into_memory(cond, left, &m_a, ID_A);
    ic_where_read_const_into_memory(cond, left, &m_1, &one, 4, IC_TYPE_INT);
    ic_where_define_condition(cond, left, m_a, m_1, IC_COND_EQ);
    ic_where_read_field_into_memory(cond, right, &m_b, ID_B);
    ic_where_read_field_into_memory(cond, right, &m_c, ID_C);
    ic_where_read_const_into_memory(cond, right, &m_3, &three, 4, IC_TYPE_INT);
    ic_where_define_calculation(cond, right, &m_sum, m_c, m_3, IC_PLUS);
    ic_where_define_condition(cond, right, m_b, m_sum, IC_COND_LT);
    ic_where_evaluate(cond);

  If the top node is a comparison, start with ic_where_define_first(); if
  it is NOT, with ic_where_define_not(). ic_where_evaluate() compiles the
  program for the RonDB 26.10 interpreter and reports errors such as type
  mismatches or IC_ERROR_CONDITION_TOO_COMPLEX (more than 8 live values
  in release 0.1). LIKE runs in the data node; a regular expression is
  evaluated by the API after the row has been read.
*/
int ic_where_define_boolean(IC_WHERE_CONDITION *cond,
                            uint32_t current_subroutine_id,
                            uint32_t *left_subroutine_id,
                            uint32_t *right_subroutine_id,
                            IC_BOOLEAN_TYPE boolean_type);
int ic_where_define_condition(IC_WHERE_CONDITION *cond,
                              uint32_t current_subroutine_id,
                              uint32_t left_memory_address,
                              uint32_t right_memory_address,
                              IC_COMPARATOR_TYPE comp_type);
int ic_where_read_field_into_memory(IC_WHERE_CONDITION *cond,
                                    uint32_t current_subroutine_id,
                                    uint32_t *memory_address,
                                    uint32_t field_id);
int ic_where_read_const_into_memory(IC_WHERE_CONDITION *cond,
                                    uint32_t current_subroutine_id,
                                    uint32_t *memory_address,
                                    const void *const_ptr,
                                    uint32_t const_len,
                                    IC_FIELD_TYPE const_type);
int ic_where_define_calculation(IC_WHERE_CONDITION *cond,
                                uint32_t current_subroutine_id,
                                uint32_t *returned_memory_address,
                                uint32_t left_memory_address,
                                uint32_t right_memory_address,
                                IC_CALCULATION_TYPE calc_type);
int ic_where_define_not(IC_WHERE_CONDITION *cond,
                        uint32_t current_subroutine_id,
                        uint32_t *subroutine_id);
int ic_where_define_first(IC_WHERE_CONDITION *cond,
                          uint32_t current_subroutine_id,
                          uint32_t *subroutine_id);
/* LIKE / regular expression on a field, or on the byte range
   [start_pos, end_pos) of it when use_full_field is 0. The pattern is a
   constant loaded into memory first. */
int ic_where_define_like(IC_WHERE_CONDITION *cond,
                         uint32_t current_subroutine_id,
                         uint32_t field_id,
                         int use_full_field,
                         uint32_t start_pos,
                         uint32_t end_pos,
                         uint32_t pattern_memory_address);
int ic_where_define_regexp(IC_WHERE_CONDITION *cond,
                           uint32_t current_subroutine_id,
                           uint32_t field_id,
                           int use_full_field,
                           uint32_t start_pos,
                           uint32_t end_pos,
                           uint32_t pattern_memory_address);
int ic_where_evaluate(IC_WHERE_CONDITION *cond);
const IC_APID_ERROR *ic_where_get_error(IC_WHERE_CONDITION *cond);
void ic_where_free(IC_WHERE_CONDITION *cond);

/* ------------------------------------------------------------------ */
/* IC_CONDITIONAL_ASSIGNMENT                                           */
/* ------------------------------------------------------------------ */

/*
  An assignment computes a value from fields and constants and writes it
  into one field; the last call is always ic_cond_assign_write_field().
  a = a * (b + 1) becomes:

    ic_cond_assign_read_field_into_memory(as, &m_a, ID_A);
    ic_cond_assign_read_field_into_memory(as, &m_b, ID_B);
    ic_cond_assign_read_const_into_memory(as, &m_1, &one, 4, IC_TYPE_INT);
    ic_cond_assign_define_calculation(as, &m_sum, m_b, m_1, IC_PLUS);
    ic_cond_assign_define_calculation(as, &m_res, m_a, m_sum,
                                      IC_MULTIPLICATION);
    ic_cond_assign_write_field(as, m_res, ID_A);

  Optionally the assignment is guarded by a WHERE condition created with
  ic_cond_assign_create_condition() or mapped from the global object.
*/
int ic_cond_assign_create_condition(IC_CONDITIONAL_ASSIGNMENT *assign,
                                    IC_WHERE_CONDITION **cond);
int ic_cond_assign_map_condition(IC_CONDITIONAL_ASSIGNMENT *assign,
                                 uint32_t global_cond_id);
int ic_cond_assign_read_field_into_memory(IC_CONDITIONAL_ASSIGNMENT *assign,
                                          uint32_t *memory_address,
                                          uint32_t field_id);
int ic_cond_assign_read_const_into_memory(IC_CONDITIONAL_ASSIGNMENT *assign,
                                          uint32_t *memory_address,
                                          const void *const_ptr,
                                          uint32_t const_len,
                                          IC_FIELD_TYPE const_type);
int ic_cond_assign_define_calculation(IC_CONDITIONAL_ASSIGNMENT *assign,
                                      uint32_t *returned_memory_address,
                                      uint32_t left_memory_address,
                                      uint32_t right_memory_address,
                                      IC_CALCULATION_TYPE calc_type);
int ic_cond_assign_write_field(IC_CONDITIONAL_ASSIGNMENT *assign,
                               uint32_t memory_address,
                               uint32_t field_id);
const IC_APID_ERROR *
ic_cond_assign_get_error(IC_CONDITIONAL_ASSIGNMENT *assign);
void ic_cond_assign_free(IC_CONDITIONAL_ASSIGNMENT *assign);

/* ------------------------------------------------------------------ */
/* IC_APID_ERROR helpers                                               */
/* ------------------------------------------------------------------ */

void ic_apid_error_init(IC_APID_ERROR *error);        /* set to "no error" */
const char *ic_apid_error_message(int32_t code);     /* text for any code */
IC_ERROR_CATEGORY ic_apid_error_category(int32_t code);
IC_ERROR_SEVERITY_LEVEL ic_apid_error_severity(int32_t code);

/* ------------------------------------------------------------------ */
/* Program scaffolding (optional)                                      */
/* ------------------------------------------------------------------ */

/*
  For programs that want the iClaustron thread-pool driven structure:
  ic_start_program parses the standard command line options
  (--ndb-connectstring, --node-id, --num-threads, --debug-level, ...),
  ic_start_apid_program connects the global object, ic_run_apid_program
  starts num_threads user threads each with its own connection and runs
  the given function in them until all return, ic_stop_apid_program
  frees everything. Applications are free to ignore this section and
  use ic_apid_global_connect() directly.
*/
typedef struct ic_thread_state IC_THREAD_STATE;
typedef int (*IC_RUN_APID_THREAD_FUNC)(IC_APID_CONNECTION *conn,
                                       IC_THREAD_STATE *thread_state);

int ic_start_program(int argc, char **argv, const char *program_name,
                     IC_GLOBAL_OPTIONS *options,
                     const char **connectstring,
                     uint32_t *num_threads);
int ic_start_apid_program(const char *connectstring,
                          const IC_GLOBAL_OPTIONS *options,
                          IC_APID_GLOBAL **global,
                          IC_APID_ERROR *error);
int ic_run_apid_program(IC_APID_GLOBAL *global,
                        uint32_t num_threads,
                        IC_RUN_APID_THREAD_FUNC thread_func);
void ic_stop_apid_program(IC_APID_GLOBAL *global);

/* Thread state helpers usable from IC_RUN_APID_THREAD_FUNC. */
uint32_t ic_thread_state_get_id(IC_THREAD_STATE *thread_state);
int ic_thread_state_get_stop_flag(IC_THREAD_STATE *thread_state);

